-- Account addresses and balance ledger. Legacy orders/receipts remain intact.
CREATE TABLE IF NOT EXISTS membership_address_owners(id INTEGER PRIMARY KEY,address TEXT NOT NULL UNIQUE,account_id TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS membership_owner_account ON membership_address_owners(account_id,id);
CREATE TABLE IF NOT EXISTS membership_account_wallets(account_id TEXT PRIMARY KEY,address_id INTEGER NOT NULL UNIQUE,address TEXT NOT NULL UNIQUE,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS membership_balances(account_id TEXT PRIMARY KEY,units TEXT NOT NULL DEFAULT '0');
CREATE TABLE IF NOT EXISTS membership_account_state(account_id TEXT PRIMARY KEY,plan TEXT NOT NULL DEFAULT '',version INTEGER NOT NULL DEFAULT 0,cancel_version INTEGER NOT NULL DEFAULT 0,ack_version INTEGER NOT NULL DEFAULT 0,needs_ack INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS membership_purchases(id TEXT PRIMARY KEY,account_id TEXT NOT NULL,plan TEXT NOT NULL,months INTEGER NOT NULL,chain_id INTEGER NOT NULL,token TEXT NOT NULL,amount TEXT NOT NULL,address TEXT NOT NULL,idempotency TEXT NOT NULL,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,settled_at INTEGER,cancelled_at INTEGER,cancel_reason TEXT NOT NULL DEFAULT '',kind TEXT NOT NULL DEFAULT 'purchase',list_units TEXT NOT NULL DEFAULT '10000',credit_units TEXT NOT NULL DEFAULT '0',state_version INTEGER NOT NULL DEFAULT 0,UNIQUE(account_id,idempotency));
CREATE INDEX IF NOT EXISTS membership_purchase_account ON membership_purchases(account_id,created_at);
CREATE UNIQUE INDEX IF NOT EXISTS membership_one_pending_purchase ON membership_purchases(account_id) WHERE settled_at IS NULL AND cancelled_at IS NULL;
CREATE TABLE IF NOT EXISTS membership_balance_events(id TEXT PRIMARY KEY,account_id TEXT NOT NULL,kind TEXT NOT NULL,units TEXT NOT NULL,chain_id INTEGER,tx TEXT,log_index INTEGER,order_id TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS membership_balance_event_account ON membership_balance_events(account_id,created_at);
CREATE TABLE IF NOT EXISTS membership_value_lots(id TEXT PRIMARY KEY,account_id TEXT NOT NULL,starts_at INTEGER NOT NULL,ends_at INTEGER,units TEXT NOT NULL,consumed_at INTEGER);
CREATE INDEX IF NOT EXISTS membership_lot_account ON membership_value_lots(account_id,consumed_at);
-- Old unpaid orders are archived as cancelled; old receiving addresses remain owned aliases.
INSERT OR IGNORE INTO membership_address_owners SELECT a.id,o.address,o.account_id,o.created_at FROM membership_addresses a JOIN membership_orders o ON o.id=a.order_id;
INSERT OR IGNORE INTO membership_account_wallets SELECT a.account_id,a.id,a.address,a.created_at FROM membership_address_owners a WHERE a.id=(SELECT MIN(b.id) FROM membership_address_owners b WHERE b.account_id=a.account_id);
INSERT OR IGNORE INTO membership_purchases(id,account_id,plan,months,chain_id,token,amount,address,idempotency,created_at,expires_at,settled_at,cancelled_at,cancel_reason,kind)
SELECT id,account_id,plan,months,chain_id,token,amount,address,idempotency,created_at,expires_at,settled_at,CASE WHEN settled_at IS NULL THEN CAST(strftime('%s','now') AS INTEGER)*1000 ELSE NULL END,CASE WHEN settled_at IS NULL THEN 'legacy' ELSE '' END,'legacy' FROM membership_orders;
INSERT OR IGNORE INTO membership_account_state(account_id,plan) SELECT o.account_id,o.plan FROM membership_orders o WHERE o.settled_at IS NOT NULL AND o.id=(SELECT p.id FROM membership_orders p WHERE p.account_id=o.account_id AND p.settled_at IS NOT NULL ORDER BY p.settled_at DESC,p.id DESC LIMIT 1);
INSERT OR IGNORE INTO membership_value_lots SELECT o.id,o.account_id,MAX(c.created_at,COALESCE((SELECT MAX(p.expires_at) FROM membership_changes p WHERE p.account_id=c.account_id AND p.created_at<c.created_at),c.created_at)),NULLIF(c.expires_at,0),o.amount,NULL FROM membership_orders o JOIN membership_changes c ON c.order_id=o.id WHERE o.settled_at IS NOT NULL;
CREATE TRIGGER IF NOT EXISTS membership_purchase_cancel_guard AFTER UPDATE OF cancelled_at ON membership_purchases WHEN OLD.cancelled_at IS NULL AND NEW.cancelled_at IS NOT NULL AND NEW.cancel_reason IN ('user','expired') BEGIN UPDATE membership_account_state SET cancel_version=cancel_version+1,needs_ack=CASE WHEN EXISTS(SELECT 1 FROM membership_balances WHERE account_id=NEW.account_id AND units<>'0') THEN 1 ELSE needs_ack END WHERE account_id=NEW.account_id; END;
INSERT OR IGNORE INTO membership_account_state(account_id,cancel_version) SELECT DISTINCT account_id,1 FROM membership_orders WHERE settled_at IS NULL;
UPDATE membership_account_state SET cancel_version=MAX(cancel_version,1) WHERE EXISTS(SELECT 1 FROM membership_orders o WHERE o.account_id=membership_account_state.account_id AND o.settled_at IS NULL);
